param([Parameter(Mandatory=$true)][string]$Worker,[Parameter(Mandatory=$true)][string]$TaskId)
$ErrorActionPreference='Stop'; Set-Location (Split-Path $PSScriptRoot -Parent); $dag=Get-Content -Raw .agent-orchestration/dag.json|ConvertFrom-Json; $n=$dag.nodes|Where-Object id -eq $TaskId; if(!$n){throw 'Unknown task'}; $root=(Get-Content -Raw .agent-orchestration/config.json|ConvertFrom-Json).worktree_root; $wt=Join-Path (Get-Location) "$root/$Worker-$TaskId"; $branch="agent-$Worker-$TaskId"; if(Test-Path $wt){throw "Worktree exists: $wt"}; & git worktree add -b $branch $wt; if($LASTEXITCODE -ne 0){throw "git worktree add failed with exit code $LASTEXITCODE"}; Write-Output "WORKTREE=$wt`nBRANCH=$branch`nTASK=$TaskId"
